#!/bin/sh
# Check every stage 0 data module, then judge it under NbE, one module at a time (nice'd).
# Requires stage0/ generated by stage0_to_fstar.py. Writes stage0-timings.txt.
cd "$(dirname "$0")"
out=stage0-timings.txt; : > $out
t0=$(date +%s)
while read n a r u; do
  i=$(python3 -c "import sys; print(''.join(p[:1].upper()+p[1:] for p in sys.argv[1].split('-')))" $n)
  d=$(./check.sh stage0/Stage0.Data.$i.fst 2>/dev/null | tail -1)
  j=$(./check.sh stage0/Stage0.Judge.$i.fst --use_nbe true 2>/dev/null | tail -1)
  echo "$n expected=$a/$r/$u | $d | $j" | tee -a $out
done < ../tests/shen-jit/stage0-accepted.txt
echo "total wall $(( $(date +%s) - t0 ))s" | tee -a $out
